/**
 * @summary Revoke one owned browser session
 */
export const authRevokeSessionPathSessionIdMin = 22
export const authRevokeSessionPathSessionIdMax = 22

export const authRevokeSessionPathSessionIdRegExp = new RegExp(
  '^[A-Za-z0-9_-]{22}$',
)

export const AuthRevokeSessionParams = zod.strictObject({
  sessionId: zod
    .string()
    .min(authRevokeSessionPathSessionIdMin)
    .max(authRevokeSessionPathSessionIdMax)
    .regex(authRevokeSessionPathSessionIdRegExp),
})

